(() => {
  const stages=['review','notices','resolution','court','judgment','possession','closed'];
  const tabs=['overview','notices','communication','dates & tasks','expenses','court','closeout','documents','history'];
  const kinds={'notices':'notice','communication':'communication','dates & tasks':'task','expenses':'expense','court':'court','closeout':'closeout'};
  const fields={
    notice:[['noticeType','Notice type','select','pay-or-vacate|vacate|termination|other'],['status','Status','select','draft|approved|sent|served|failed|withdrawn'],['occurredAt','Notice / service date','datetime-local'],['dueAt','Reviewed deadline','datetime-local'],['method','Delivery method'],['recipient','Recipient'],['server','Served by'],['amount','Amount stated','number']],
    communication:[['channel','Channel','select','call|email|text|letter|meeting|internal-note'],['recipient','Participants / recipient'],['occurredAt','Date','datetime-local']],
    task:[['owner','Case manager'],['dueAt','Due date','datetime-local'],['status','Status','select','open|completed']],
    expense:[['expenseId','Expense ledger record','expense'],['category','Category','select','filing|service|attorney|mediation|enforcement|storage|turnover|other']],
    court:[['eventType','Event','select','filing|citation-service|hearing|continuance|settlement|judgment|appeal|stay|writ|other'],['occurredAt','Event date','datetime-local'],['dueAt','Next deadline','datetime-local'],['court','Court / precinct'],['caseNumber','Case number'],['location','Location / remote link'],['attendees','Attendees'],['outcome','Outcome']],
    closeout:[['eventType','Event','select','voluntary-surrender|authorized-enforcement|inspection|keys-returned|belongings|deposit-accounting|refund|tenant-charge-approved|judgment-award|recovery|write-off|turnover|other'],['occurredAt','Date','datetime-local'],['amount','Amount, if applicable','number']]
  };
  const esc=value=>String(value??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
  const pretty=v=>String(v||'').replace(/-/g,' ').replace(/^./,c=>c.toUpperCase());
  const date=v=>v?new Date(v).toLocaleString():'—';
  const money=v=>new Intl.NumberFormat('en-US',{style:'currency',currency:'USD'}).format(Number(v)||0);
  let view,record,documents=[],expenses=[],cases=[],tab='overview',tenantFilter='',returnAction=null,returnFocus,returnY,request=0;
  async function api(path='',method='GET',data){
    const headers={};if(data&&!(data instanceof FormData))headers['Content-Type']='application/json';
    const response=await fetch('/api/eviction-cases'+path,{method,headers,body:data?data instanceof FormData?data:JSON.stringify(data):undefined});
    if(!response.ok){const e=await response.json().catch(()=>({}));throw Error(e.error||'Unable to save case.');}return response.json();
  }
  function frame(){
    const host=document.querySelector('main.main-content');
    if(!host)throw Error('Property workspace unavailable.');
    if(!view){view=document.createElement('section');view.id='evictionCaseWorkspace';host.append(view);}
    if(!host.classList.contains('eviction-cases-open')){returnFocus=document.activeElement;returnY=window.scrollY;}
    host.classList.add('eviction-cases-open');view.hidden=false;
    view.oninput=view.onchange=event=>{if(event.target.closest('form'))dirty=true;};
    if(!record)view.scrollIntoView({block:'start',behavior:'auto'});
  }
  function error(message){let el=view.querySelector('.ec-error');if(!el){el=document.createElement('div');el.className='ec-error';el.setAttribute('role','alert');view.prepend(el);}el.textContent=message;if(record&&/refresh|reload|changed/i.test(message)){const retry=document.createElement('button');retry.type='button';retry.textContent='Reload case';retry.onclick=()=>{if(!canLeave())return;dirty=false;loadCase(record._id);};el.append(retry);}el.scrollIntoView({block:'nearest'});}
  function header(title,back='Back to overview'){return `<header class="ec-header"><button type="button" data-ec-back>← ${back}</button><div><span class="ec-eyebrow">EVICTION-CASE</span><h2>${esc(title)}</h2></div></header>`;}
  function exit(){if(!canLeave())return;dirty=false;request++;view.hidden=true;document.querySelector('main.main-content')?.classList.remove('eviction-cases-open');returnFocus?.focus({preventScroll:true});window.scrollTo(0,returnY||0);}
  function bindBack(fn){view.querySelector('[data-ec-back]').onclick=fn;}
  window.openEvictionCases=async function(tenantId=''){
    if(!canLeave())return;dirty=false;record=null;returnAction=null;tenantFilter=String(tenantId||'');frame();view.innerHTML=header('Eviction cases')+'<p>Loading cases…</p>';bindBack(exit);const ticket=++request;
    try{cases=await api(tenantFilter?'?tenantId='+encodeURIComponent(tenantFilter):'');if(ticket!==request)return;if(tenantFilter){const current=cases.find(c=>c.active)||cases[0];tab='overview';if(current){await loadCase(current._id);return;}renderCreate();return;}renderList();}catch(e){if(ticket===request)error(e.message);}
  };
  window.openEvictionCase=async function(id,onReturn){
    if(!canLeave())return;dirty=false;record=null;tenantFilter='';returnAction=typeof onReturn==='function'?onReturn:null;tab='overview';frame();await loadCase(String(id||''));
  };
  function renderList(){
    record=null;view.innerHTML=header('Eviction cases')+`<div class="ec-tools"><button data-ec-new>+ Start eviction</button><label>Stage<select id="ec-stage-filter"><option value="all">All stages</option>${stages.map(s=>`<option>${s}</option>`).join('')}</select></label><label>Search<input id="ec-search" type="search" placeholder="Tenant, property or case manager"></label></div><p class="ec-muted">Property cases · Shared workspace. Sending notices and filing with the court are recorded here after you perform them.</p><div class="ec-list"></div>`;
    bindBack(exit);view.querySelector('[data-ec-new]').onclick=renderCreate;
    const list=()=>{const stage=view.querySelector('#ec-stage-filter').value,q=view.querySelector('#ec-search').value.toLowerCase();const shown=cases.filter(c=>(stage==='all'||c.stage===stage)&&[c.snapshot?.tenantName,c.snapshot?.propertyName,c.owner].join(' ').toLowerCase().includes(q));view.querySelector('.ec-list').innerHTML=shown.length?`<div class="ec-scroll"><table><thead><tr><th>Tenant</th><th>Property</th><th>Stage</th><th>Case manager</th><th>Next action</th><th>Due</th><th></th></tr></thead><tbody>${shown.map(c=>`<tr><td>${esc(c.snapshot?.tenantName)}</td><td>${esc(c.snapshot?.propertyName)}</td><td>${esc(pretty(c.stage))}${c.hold!=='active'?` · ${esc(pretty(c.hold))}`:''}</td><td>${esc(c.owner)}</td><td>${esc(c.nextAction||'—')}</td><td class="${c.active&&c.dueAt&&new Date(c.dueAt)<new Date()?'ec-overdue':''}">${esc(date(c.dueAt))}</td><td><button data-open="${esc(c._id)}">Open →</button></td></tr>`).join('')}</tbody></table></div>`:'<p class="ec-empty">No cases match this view.</p>';view.querySelectorAll('[data-open]').forEach(b=>b.onclick=()=>loadCase(b.dataset.open));};
    view.querySelector('#ec-stage-filter').onchange=list;view.querySelector('#ec-search').oninput=list;list();
  }
  function input(key,label,type='text',value='',options=''){
    let control;
    if(type==='select')control=`<select name="${key}">${options.split('|').map(v=>`<option value="${esc(v)}" ${v===value?'selected':''}>${esc(pretty(v))}</option>`).join('')}</select>`;
    else if(type==='textarea')control=`<textarea name="${key}" rows="3" maxlength="10000">${esc(value)}</textarea>`;
    else if(type==='expense')control=`<select name="expenseId" required><option value="">Select an existing expense</option>${expenses.map(e=>`<option value="${esc(e._id)}">${esc(e.description||e.category||'Expense')} · ${esc(date(e.date||e.createdAt))}</option>`).join('')}</select>`;
    else control=`<input name="${key}" type="${type}" value="${esc(value)}" ${type==='number'?'min="0" step="0.01"':'maxlength="500"'}>`;
    const suggestions=type==='text'?fieldSuggestions(key):[];if(suggestions.length){control=control.replace('<input ',`<input list="ec-suggest-${key}" autocomplete="off" `)+`<datalist id="ec-suggest-${key}">${suggestions.map(v=>`<option value="${esc(v)}"></option>`).join('')}</datalist>`;}return `<label>${esc(label)}${control}</label>`;
  }
  function renderCreate(){
    const tenants=[...(state.allTenants||[]),...(state.tenants||[])].filter((t,i,a)=>a.findIndex(x=>String(x._id)===String(t._id))===i).filter(t=>!tenantFilter||String(t._id)===tenantFilter);
    view.innerHTML=header('Start eviction',tenantFilter?'Back to tenant':'Back to cases')+`<form id="ec-create" class="ec-form"><label>Tenant<select name="tenantId" required><option value="">Select tenant</option>${tenants.map(t=>`<option value="${esc(t._id)}" ${String(t._id)===tenantFilter?'selected':''} ${t.leaseType!=='fmr'?'disabled':''}>${esc(t.name)}${t.leaseType!=='fmr'?' — subsidized / unconfirmed':''}</option>`).join('')}</select></label>${input('reason','Reason','select','','nonpayment|lease-violation|holdover|other')}${input('owner','Case manager')}${input('county','County','text','Bexar')}${input('precinct','Verified JP precinct')}<p class="ec-wide ec-muted">This creates an internal case. It does not serve a notice, file an eviction, charge the tenant, or change occupancy.</p><button type="submit">Create case</button></form>`;
    bindBack(backToOrigin);view.querySelectorAll('input[name=owner],input[name=precinct]').forEach(el=>el.required=true);if(tenantFilter){const selected=view.querySelector('[name=tenantId]');selected.disabled=true;}view.querySelector('form').onsubmit=e=>saveForm(e,async data=>{data.privateMarketConfirmed=true;if(tenantFilter)data.tenantId=tenantFilter;const c=await api('','POST',data);dirty=false;rememberCase(c);flash('Case started. Add supporting documents or the next action.');tab='overview';await loadCase(c._id);});
  }
  function caseBackLabel(){return returnAction?'Back to overview':tenantFilter?'Back to tenant':'Back to cases';}
  async function loadCase(id){frame();const ticket=++request;view.innerHTML=header('Loading case',caseBackLabel());bindBack(backToOrigin);try{const result=await Promise.all([api('/'+id),api('/'+id+'/files'),api('/'+id+'/expenses')]);if(ticket!==request)return;[record,documents,expenses]=result;dirty=false;rememberCase(record);renderCase();}catch(e){if(ticket===request)error(e.message);}}
  function active(){const replaced=new Set(record.entries.filter(e=>e.supersedes).map(e=>e.supersedes));return record.entries.filter(e=>!replaced.has(String(e._id)));}
  function localTime(value){if(!value)return '';const d=new Date(value);return new Date(d.getTime()-d.getTimezoneOffset()*60000).toISOString().slice(0,16);}
  function renderCase(){
    view.innerHTML='<div class="ec-sticky-navigation">'+header(record.snapshot.tenantName+' · '+record.snapshot.propertyName,caseBackLabel())+`${smartContext()}<nav class="ec-tabs" aria-label="Case sections">${tabs.filter(t=>t!=='history').map(t=>`<button type="button" data-tab="${t}" aria-pressed="${tab===t}">${pretty(t)}${tabCount(t)}</button>`).join('')}</nav></div><div class="ec-workspace-grid"><div id="ec-content"></div><aside id="ec-history-sidebar" aria-label="Case history"></aside></div>`;
    bindBack(backToOrigin);view.querySelectorAll('[data-tab]').forEach(b=>b.onclick=()=>{if(!canLeave())return;dirty=false;tab=b.dataset.tab;renderCase();});
    const content=view.querySelector('#ec-content');
    if(tab==='overview'){
      content.innerHTML=`<p class="ec-muted">${esc(pretty(record.reason))} · ${esc(record.county)} County · Precinct ${esc(record.precinct)}. </p><details class="ec-case-settings"><summary>Edit case details</summary><form class="ec-form" id="ec-update">${input('stage','Case stage','select',record.stage,stages.join('|'))}${input('hold','Case status','select',record.hold,'active|on-hold|payment-agreement')}${input('owner','Case manager','text',record.owner)}${input('attorney','Attorney / contact','text',record.attorney)}${input('county','County','text',record.county)}${input('precinct','JP precinct','text',record.precinct)}${input('nextAction','Next action','text',record.nextAction)}${input('dueAt','Next deadline (local time)','datetime-local',localTime(record.dueAt))}${input('priorDelinquency','Prior delinquency reviewed','select',record.priorDelinquency||'unknown','unknown|yes|no')}${input('leaseNoticeClause','Lease notice clause / reviewed requirements','textarea',record.leaseNoticeClause)}${input('holdReason','Hold / stay reason','textarea',record.holdReason)}${input('closureReason','Closure reason','text',record.closureReason)}${input('closureNotes','Final accounting / resolution notes','textarea',record.closureNotes)}<button type="submit">Save case</button></form></details>`;
      content.querySelector('form').onsubmit=e=>saveForm(e,async data=>{record=await api('/'+record._id,'PATCH',{...data,revision:record.revision});dirty=false;rememberCase(record);flash('Case saved.');renderCase();});
    }else if(tab==='expenses'){
      renderExpenses(content);
    }else if(tab==='documents'){
      content.innerHTML=`<p class="ec-muted">Upload the lease, reviewed notice, service proof, court papers or inspection evidence. Each upload is retained as a separate version; reference it when adding a record.</p>${record.active?'<form id="ec-upload"><label>Document (PDF, DOCX, PNG, JPEG; 5 MB max)<input type="file" name="file" required accept=".pdf,.docx,.png,.jpg,.jpeg"></label><button>Upload document</button></form>':''}<div class="ec-files">${documents.map(f=>`<button data-file="${esc(f._id)}">${esc(f.name)} · ${esc(date(f.createdAt))}</button>`).join('')||'<p>No documents yet.</p>'}</div>`;
      content.querySelector('form')?.addEventListener('submit',e=>{e.preventDefault();const form=e.currentTarget;busy(form,async()=>{await api('/'+record._id+'/files','POST',new FormData(form));await loadCase(record._id);});});
      content.querySelectorAll('[data-file]').forEach(b=>b.onclick=()=>quickLook(b.dataset.file));
    }else if(tab==='history'){
      content.innerHTML=`<p class="ec-muted">Use Update record in the relevant tab to make changes. To withdraw an incorrect record, select it below and explain why. Earlier versions remain in history.</p>${historyView()}${record.active?`<form class="ec-form" id="ec-correction"><label class="ec-wide">Record to withdraw<select name="supersedes" required><option value="">Select record</option>${active().filter(e=>e.kind!=='correction').map(e=>`<option value="${esc(e._id)}">${esc(pretty(e.kind))} · ${esc(e.title)} · ${esc(date(e.occurredAt||e.createdAt))}</option>`).join('')}</select></label>${input('notes','Correction explanation','textarea')}<button>Withdraw record</button></form>`:''}`;
      content.querySelector('form')?.addEventListener('submit',e=>saveForm(e,data=>add({kind:'correction',title:'Record correction',...data})));
    }else{
      const kind=kinds[tab],entries=active().filter(e=>e.kind===kind);
      content.innerHTML=(kind==='expense'?`<p class="ec-note">Link an existing property expense to avoid duplicating the ledger. Case costs are not automatically tenant charges. Record approved charges, awards and recoveries separately in Closeout.</p><p>Linked case expenses: <strong>${money(entries.reduce((s,e)=>s+(Number(e.amount)||0),0))}</strong></p>`:'')+`${record.active?`<div class="ec-record-toolbar"><strong>${esc(pretty(tab))} <span class="ec-count">${entries.length}</span></strong><button type="button" data-add-record>+ Add record</button></div>`:''}${record.active?`<form class="ec-form" id="ec-entry" hidden>${input('title','Title')}${fields[kind].map(f=>input(f[0],f[1],f[2]||'text','',f[3]||'')).join('')}${kind!=='task'?`<label>Supporting document<select name="documentId"><option value="">No document selected</option>${documents.map(d=>`<option value="${esc(d._id)}">${esc(d.name)}</option>`).join('')}</select></label>`:''}${input('notes','Details, evidence and follow-up','textarea')}<div class="ec-wide ec-draft-tools"><button type="button" data-draft-note title="Generate a draft note from entered fields" aria-label="Generate a draft note from entered fields"><i class="fas fa-wand-magic-sparkles" aria-hidden="true"></i></button><small>Creates an editable starting point using only the values entered.</small></div><p class="ec-muted ec-wide">Dates use your browser’s local time. Use Documents to upload evidence first. Adding a communication record does not send a message.</p><button type="submit">Save record</button><button type="button" data-cancel-record>Cancel</button></form>`:''}<div class="ec-records">${entries.map(entry=>recordCard(entry)).join('')||'<p class="ec-empty">No records yet.</p>'}</div>`;
      content.querySelector('form')?.addEventListener('submit',e=>saveForm(e,data=>add({kind,...data}))); content.querySelectorAll('[data-complete-task]').forEach(b=>b.onclick=()=>busy(content,async()=>{record=await api('/'+record._id+'/tasks/'+b.dataset.completeTask+'/complete','POST',{revision:record.revision});renderCase();}));
    }
    bindRecordActions();
    setupCaseFlow();
    openHistory();
    bindNoteDrafts(view);
  }
  async function add(data){record=await api('/'+record._id+'/entries','POST',{...data,revision:record.revision});dirty=false;rememberCase(record);flash('Record saved.');renderCase();}
  async function busy(form,fn){if(saving)return;saving=true;const buttons=form.querySelectorAll('button');buttons.forEach(b=>b.disabled=true);view.querySelector('.ec-error')?.remove();try{await fn();}catch(e){error(e.message);}finally{saving=false;buttons.forEach(b=>b.disabled=false);}}
  function saveForm(event,fn){event.preventDefault();const form=event.currentTarget;const data=Object.fromEntries(new FormData(form));if(form.dataset.supersedes)data.supersedes=form.dataset.supersedes;for(const key of ['occurredAt','dueAt'])if(data[key])data[key]=new Date(data[key]).toISOString();return busy(form,()=>fn(data));}
  async function download(id){try{const response=await fetch(`/api/eviction-cases/${record._id}/files/${id}`,{});if(!response.ok)throw Error('Document unavailable.');const url=URL.createObjectURL(await response.blob()),a=document.createElement('a');a.href=url;a.download=documents.find(f=>f._id===id)?.name||'document';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}catch(e){error(e.message);}}
  let labelCases=null,labelRequest=null,labelQueued=false,labelRetryAt=0,saving=false,dirty=false,successMessage='';
  function canLeave(){return !saving&&(!dirty||window.confirm('Discard unsaved changes?'));}
  function backToOrigin(){if(!canLeave())return;dirty=false;if(returnAction){const action=returnAction;returnAction=null;exit();action();}else if(tenantFilter)exit();else window.openEvictionCases();}
  function rememberCase(c){if(labelCases){labelCases=labelCases.filter(item=>String(item._id)!==String(c._id));labelCases.unshift(c);}paintTenantActions();}
  function paintTenantActions(){
    if(!labelCases)return;
    document.querySelectorAll('[data-eviction-tenant]').forEach(button=>{
      const matches=labelCases.filter(c=>String(c.tenantId)===button.dataset.evictionTenant),current=matches.find(c=>c.active)||matches[0];
      const label=current?'Eviction case':'Start eviction';
      if(button.textContent.trim()!==label)button.textContent=label;
      button.title=current?`Open ${pretty(current.stage)} case`:'Start a case for this tenant';
    });
  }
  async function refreshTenantActions(force=false){
    if(force){labelCases=null;labelRetryAt=0;}
    if(Date.now()<labelRetryAt)return;
    if(labelCases){paintTenantActions();return;}
    if(!document.querySelector('[data-eviction-tenant]'))return;
    if(!labelRequest)labelRequest=api().then(items=>{labelCases=items;paintTenantActions();}).catch(()=>{labelRetryAt=Date.now()+30000;}).finally(()=>{labelRequest=null;});
    await labelRequest;
  }
  function setupTenantActions(){
    refreshTenantActions();
    const observer=new MutationObserver(()=>{if(labelQueued)return;labelQueued=true;requestAnimationFrame(()=>{labelQueued=false;refreshTenantActions();});});
    observer.observe(document.querySelector('main.main-content')||document.body,{childList:true,subtree:true});
    window.addEventListener('focus',()=>refreshTenantActions(true));
  }
  if(document.readyState==='loading')document.addEventListener('DOMContentLoaded',setupTenantActions,{once:true});else setupTenantActions();
  function flash(message){successMessage=message;}
  function setupCaseFlow(){
    if(successMessage){const el=document.createElement('div');el.className='ec-success';el.setAttribute('role','status');el.textContent=successMessage;view.querySelector('#ec-content').prepend(el);successMessage='';}
    view.oninput=event=>{if(event.target.closest('form'))dirty=true;};
    view.onchange=event=>{if(event.target.closest('form'))dirty=true;};
    view.querySelectorAll('form input[name="title"],form input[name="owner"]').forEach(el=>el.required=true);
    const editForm=view.querySelector('#ec-update');
    if(editForm){
      const update=()=>{
        const stage=editForm.querySelector('[name="stage"]').value,hold=editForm.querySelector('[name="hold"]').value;
        ['closureReason','closureNotes'].forEach(name=>{const el=editForm.querySelector(`[name="${name}"]`);el.closest('label').hidden=stage!=='closed';el.required=stage==='closed';});
        const reason=editForm.querySelector('[name="holdReason"]');reason.closest('label').hidden=hold!=='on-hold';reason.required=hold==='on-hold';
      };editForm.querySelector('[name="stage"]').addEventListener('change',update);editForm.querySelector('[name="hold"]').addEventListener('change',update);update();
      const tasks=active().filter(e=>e.kind==='task'&&e.status==='open').sort((a,b)=>new Date(a.dueAt)-new Date(b.dueAt));
      const nextByStage={review:['Review the lease and supporting documents','documents'],notices:['Prepare the notice and record service','notices'],resolution:['Record the resolution discussion and follow-up','communication'],court:['Review hearings and court deadlines','court'],judgment:['Record the court decision and supporting document','court'],possession:['Record possession and final accounting','closeout']};const recommended=!record.active?['Review the closed case history','history']:record.hold==='on-hold'?['Review the hold before advancing','overview']:record.hold==='payment-agreement'?['Review the payment agreement and follow-up','communication']:nextByStage[record.stage]||nextByStage.review;
      const panel=document.createElement('div');panel.className='ec-guidance';panel.innerHTML=`<div><strong>Next step</strong><p>${esc(record.nextAction||recommended[0])}</p><button type="button" data-next-tab="${recommended[1]}">Open ${pretty(recommended[1])} →</button></div><div><strong>${tasks.length} open tasks</strong>${tasks.slice(0,3).map(t=>`<p class="${new Date(t.dueAt)<new Date()?'ec-overdue':''}">${esc(t.title)} · ${esc(date(t.dueAt))}</p>`).join('')||'<p>No open tasks.</p>'}<button type="button" data-next-tab="dates & tasks">Manage tasks →</button></div>`;editForm.closest('.ec-case-settings').before(panel);
      panel.querySelectorAll('[data-next-tab]').forEach(b=>b.onclick=()=>{if(!canLeave())return;dirty=false;if(b.dataset.nextTab==='history'){sidebarTab='history';openHistory();return;}if(b.dataset.nextTab==='overview'){editForm.closest('.ec-case-settings').open=true;editForm.scrollIntoView({block:'nearest'});return;}tab=b.dataset.nextTab;renderCase();});
    }
    view.querySelectorAll('[data-edit-entry]').forEach(button=>button.onclick=()=>{
      if(!canLeave())return;
      const item=active().find(e=>String(e._id)===button.dataset.editEntry),form=view.querySelector('#ec-entry');if(!item||!form)return;
      form.reset();for(const [key,value] of Object.entries(item)){const el=form.elements.namedItem(key);if(el)el.value=['occurredAt','dueAt'].includes(key)?localTime(value):value;}
      form.dataset.supersedes=String(item._id);form.hidden=false;setRecordButton(true);form.querySelector('button[type="submit"]').textContent='Save updated record';dirty=false;form.scrollIntoView({block:'nearest'});form.querySelector('[name="title"]').focus();
    });
  }
  function expenseAmount(e){const lines=(e.lineItems||[]).filter(l=>String(l.projectId)===String(record.projectId));return lines.length?lines.reduce((s,l)=>s+(Number(l.amount)||0),0):Number(e.receiptTotal??e.amount??0);}
  function renderExpenses(content){
    const linked=active().filter(e=>e.kind==='expense'),ids=new Set(linked.map(e=>e.expenseId));
    const available=expenses.filter(e=>!ids.has(String(e._id))&&!['archived','rejected'].includes(e.status));
    const rows=linked.map(entry=>{const ledger=expenses.find(e=>String(e._id)===entry.expenseId);return {...entry,title:ledger?.description||entry.title,vendor:ledger?.vendor||entry.vendor,amount:ledger?expenseAmount(ledger):entry.amount,status:ledger?.status||entry.status,occurredAt:ledger?.date||entry.occurredAt};});
    content.innerHTML=`<div class="ec-tools"><strong>Case expenses · ${money(rows.reduce((s,e)=>s+Number(e.amount||0),0))}</strong>${record.active?'<button type="button" data-expense-mode="new">+ Add expense</button><button type="button" data-expense-mode="link">Link existing</button>':''}</div><p class="ec-muted">New expenses are saved to this property’s ledger as Waiting for review. They do not become tenant charges.</p><div id="ec-expense-editor"></div><div class="ec-scroll"><table><thead><tr><th>Date</th><th>Description</th><th>Vendor</th><th>Category</th><th>Status</th><th>Amount</th><th>Receipt</th></tr></thead><tbody>${rows.map(e=>`<tr><td>${esc(date(e.occurredAt))}</td><td>${esc(e.title)}</td><td>${esc(e.vendor||'—')}</td><td>${esc(pretty(e.category))}</td><td>${esc(e.status==='pending_review'?'Waiting for review':pretty(e.status))}</td><td>${money(e.amount)}</td><td>${e.documentId?`<button type="button" data-receipt="${esc(e.documentId)}">Open receipt</button>`:'—'}</td></tr>`).join('')}</tbody></table>${!rows.length?'<p class="ec-empty">No expenses yet. Add an expense or link one already in the ledger.</p>':''}</div>`;
    content.querySelectorAll('[data-receipt]').forEach(b=>b.onclick=()=>quickLook(b.dataset.receipt));
    content.querySelectorAll('[data-expense-mode]').forEach(b=>b.onclick=()=>{
      if(!canLeave())return;dirty=false;const creating=b.dataset.expenseMode==='new',editor=content.querySelector('#ec-expense-editor');if(editor.dataset.mode===b.dataset.expenseMode){editor.innerHTML='';delete editor.dataset.mode;setExpenseButtons(content,'');return;}editor.dataset.mode=b.dataset.expenseMode;setExpenseButtons(content,b.dataset.expenseMode);
      editor.innerHTML=`<form class="ec-form" id="ec-expense-form"><h3 class="ec-wide">${creating?'Add expense':'Link existing expense'}</h3>${creating?`${input('title','Description')}${input('vendor','Vendor / payee')}${input('occurredAt','Expense date','date',new Date().toLocaleDateString('en-CA'))}${input('amount','Amount','number')}`:`<label class="ec-wide">Property expense<select name="expenseId" required><option value="">Select expense</option>${available.map(e=>`<option value="${esc(e._id)}">${esc(e.description||'Expense')} · ${money(expenseAmount(e))} · ${esc(date(e.date||e.createdAt))}</option>`).join('')}</select></label>${!available.length?'<p class="ec-wide ec-muted">No unlinked expenses. Choose Add expense to create one.</p>':''}`} ${input('category','Category','select','','filing|service|attorney|mediation|enforcement|storage|turnover|other')}<label>Saved receipt<select name="documentId"><option value="">None</option>${documents.map(d=>`<option value="${esc(d._id)}">${esc(d.name)}</option>`).join('')}</select></label><label>Or upload receipt<input name="receipt" type="file" accept=".pdf,.docx,.png,.jpg,.jpeg"></label>${input('notes','Notes','textarea')}<button type="submit">${creating?'Save expense':'Link expense'}</button><button type="button" data-cancel-expense>Cancel</button></form>`;
      const form=editor.querySelector('form');if(creating)for(const name of ['title','vendor','occurredAt','amount'])form.elements.namedItem(name).required=true;
      let creationId=Array.from(crypto.getRandomValues(new Uint8Array(12)),n=>n.toString(16).padStart(2,'0')).join(''),uploadedReceipt='';
      form.elements.namedItem('receipt').onchange=()=>{uploadedReceipt='';};
      form.querySelector('[data-cancel-expense]').onclick=()=>{if(canLeave()){dirty=false;editor.innerHTML='';delete editor.dataset.mode;setExpenseButtons(content,'');}};
      form.onsubmit=e=>{e.preventDefault();busy(form,async()=>{
        const data=Object.fromEntries(new FormData(form));delete data.receipt;
        const file=form.elements.namedItem('receipt').files[0];
        if(file&&!uploadedReceipt){const upload=new FormData();upload.append('file',file);uploadedReceipt=(await api('/'+record._id+'/files','POST',upload)).id;record=await api('/'+record._id);documents=await api('/'+record._id+'/files');}
        if(uploadedReceipt)data.documentId=uploadedReceipt;
        if(creating){data.occurredAt=new Date(data.occurredAt+'T12:00:00').toISOString();record=await api('/'+record._id+'/expenses','POST',{...data,creationId,revision:record.revision});}
        else {const chosen=available.find(item=>String(item._id)===data.expenseId);if(!chosen)throw Error('Select an expense.');record=await api('/'+record._id+'/entries','POST',{...data,title:chosen.description||'Expense',kind:'expense',revision:record.revision});}
        dirty=false;rememberCase(record);expenses=await api('/'+record._id+'/expenses');flash(creating?'Expense saved to the ledger and linked to this case.':'Expense linked.');renderCase();
      });};
      bindNoteDrafts(editor);editor.scrollIntoView({block:'nearest'});form.querySelector('input,select')?.focus();
    });
  }

  function tabCount(name){const count=name==='overview'?null:name==='documents'?documents.length:name==='history'?record.audit.length+record.entries.length:active().filter(e=>e.kind===kinds[name]).length;return count===null?'':` <span class="ec-count">${count}</span>`;}
  function documentButton(id){if(!id)return '';const file=documents.find(d=>String(d._id)===String(id));return `<button type="button" class="ec-document-link" data-preview="${esc(id)}">▤ ${esc(file?.name||'Supporting document')} <span>Quick look ↗</span></button>`;}
  function recordDetails(entry){return Object.entries(entry).filter(([k,v])=>!['_id','kind','title','recordedAt','createdAt','actor','notes','supersedes','documentId','expenseId'].includes(k)&&v!==''&&v!=null&&typeof v!=='object').map(([k,v])=>`<div><dt>${esc(pretty(k.replace(/([A-Z])/g,' $1')))}</dt><dd>${esc(k==='amount'?money(v):['occurredAt','dueAt'].includes(k)?date(v):pretty(v))}</dd></div>`).join('');}
  function recordCard(entry,history=false){const replaced=record.entries.find(e=>String(e.supersedes)===String(entry._id)),previous=record.entries.find(e=>String(e._id)===String(entry.supersedes));return `<article class="ec-record-card"><header class="ec-record-head"><div><span class="ec-record-kind">${esc(pretty(entry.kind))}${history?` · ${replaced?(replaced.kind==='correction'?'Withdrawn':'Earlier version'):'Current record'}`:''}</span><h3>${esc(entry.title)}</h3><p class="ec-muted">${esc(date(entry.recordedAt||entry.createdAt||entry.occurredAt))}${entry.actor?.identityVerified&&entry.actor?.name?' · '+esc(entry.actor.name):''}</p></div>${!history&&record.active?`<button type="button" data-edit-entry="${esc(entry._id)}">Update record</button>`:''}</header>${previous?`<p class="ec-version">${entry.kind==='correction'?'Withdraws':'Updated from'} “${esc(previous.title)}”</p>`:''}<dl>${recordDetails(entry)}</dl>${entry.notes?`<div class="ec-record-notes">${esc(entry.notes)}</div>`:''}${documentButton(entry.documentId)}${!history&&entry.kind==='task'&&entry.status==='open'&&record.active?`<footer><button type="button" data-complete-task="${esc(entry._id)}">✓ Mark completed</button></footer>`:''}</article>`;}
  function historyView(){const events=[...record.audit].sort((a,b)=>new Date(b.at)-new Date(a.at));return `<h3>Activity timeline</h3><div class="ec-history ec-timeline">${events.map(a=>`<article><header><strong>${esc(a.action)}</strong><time>${esc(date(a.at))}</time></header>${a.details?.name?`<p>${esc(a.details.name)}</p>${a.details.id?documentButton(a.details.id):''}`:''}${recordDetails(a.details||{})?`<dl>${recordDetails(Object.fromEntries(Object.entries(a.details||{}).filter(([k])=>!['id','name','revision','active'].includes(k))))}</dl>`:''}</article>`).join('')||'<p class="ec-empty">No activity yet.</p>'}</div><h3>Record versions</h3><p class="ec-muted">Newest first. Earlier versions remain available for reference.</p><div class="ec-records">${[...record.entries].reverse().map(e=>recordCard(e,true)).join('')||'<p class="ec-empty">No records yet.</p>'}</div>`;}
  function setRecordButton(open){const b=view.querySelector('[data-add-record]');if(b){b.textContent=open?'− Close form':'+ Add record';b.setAttribute('aria-expanded',String(open));b.setAttribute('aria-controls','ec-entry');}}
  function bindRecordActions(){view.querySelectorAll('[data-preview]').forEach(b=>b.onclick=()=>quickLook(b.dataset.preview));view.querySelectorAll('[data-history-open]').forEach(b=>b.onclick=openHistory);view.querySelectorAll('[data-add-record],[data-cancel-record]').forEach(b=>b.onclick=()=>{if(!canLeave())return;const form=view.querySelector('#ec-entry');if(!form)return;const opening=form.hidden;form.reset();delete form.dataset.supersedes;form.querySelector('button[type="submit"]').textContent='Save record';dirty=false;form.hidden=!opening;setRecordButton(opening);if(opening)form.querySelector('[name="title"]').focus();});}
  async function quickLook(id){const file=documents.find(d=>String(d._id)===String(id)),dialog=document.createElement('dialog');dialog.className='ec-preview';dialog.innerHTML=`<header><h3>${esc(file?.name||'Document preview')}</h3><button type="button" data-download>Download</button><button type="button" data-close aria-label="Close document preview">✕</button></header><div class="ec-preview-body" role="status">Loading document…</div>`;document.body.append(dialog);let url;dialog.querySelector('[data-close]').onclick=()=>dialog.close();dialog.querySelector('[data-download]').onclick=()=>download(id);dialog.addEventListener('close',()=>{if(url)URL.revokeObjectURL(url);dialog.remove();});dialog.showModal();try{const response=await fetch(`/api/eviction-cases/${record._id}/files/${id}`);if(!response.ok)throw Error('Document unavailable. Close this preview and try again.');const blob=await response.blob();if(!dialog.open)return;url=URL.createObjectURL(blob);const body=dialog.querySelector('.ec-preview-body');body.textContent='';if(['image/png','image/jpeg'].includes(blob.type)){const img=document.createElement('img');img.src=url;img.alt=file?.name||'Supporting document';body.append(img);}else if(blob.type==='application/pdf'){const frame=document.createElement('iframe');frame.src=url;frame.title=file?.name||'PDF preview';body.append(frame);}else body.textContent='Preview is unavailable for this file type. Choose Download to open it on your device.';}catch(e){if(dialog.open)dialog.querySelector('.ec-preview-body').textContent=e.message;}}

  function smartContext(){const tasks=active().filter(e=>e.kind==='task'&&e.status==='open'),overdue=tasks.filter(e=>e.dueAt&&new Date(e.dueAt)<new Date()).length;return `<div class="ec-context ec-smart-context"><div><span class="ec-record-kind">Case progress</span><strong>${esc(pretty(record.stage))}</strong><span class="ec-status">${record.active?esc(pretty(record.hold)):'Closed'}</span></div><div><small>Case manager</small><strong>${esc(record.owner||'Assign a case manager')}</strong></div><div><small>Next action</small><strong>${esc(record.nextAction||(record.active?'Set the next action':'Case resolved'))}</strong>${record.dueAt?`<span class="${record.active&&new Date(record.dueAt)<new Date()?'ec-overdue':''}">${esc(date(record.dueAt))}</span>`:'<span>No deadline set</span>'}</div><div><small>Follow-up</small><strong>${tasks.length} open tasks</strong><span class="${overdue?'ec-overdue':''}">${overdue?overdue+' overdue':'No overdue tasks'}</span></div>${record.hold==='on-hold'&&record.holdReason?`<p class="ec-wide ec-note">On hold: ${esc(record.holdReason)}</p>`:''}</div>`;}
  let sidebarTab='tasks';
  function openHistory(){const panel=view.querySelector('#ec-history-sidebar');if(!panel)return;panel.innerHTML=`<header class="ec-panel-head ec-sidebar-tabs"><div role="tablist" aria-label="Case sidebar">${['tasks','history'].map(name=>`<button type="button" role="tab" id="ec-side-tab-${name}" data-side-tab="${name}" aria-controls="ec-side-panel-${name}" aria-selected="${sidebarTab===name}" tabindex="${sidebarTab===name?0:-1}">${pretty(name)} <span class="ec-count">${name==='tasks'?active().filter(e=>e.kind==='task'&&e.status==='open').length:record.audit.length+record.entries.length}</span></button>`).join('')}</div></header><div class="ec-panel-body"><section id="ec-side-panel-tasks" role="tabpanel" aria-labelledby="ec-side-tab-tasks" ${sidebarTab!=='tasks'?'hidden':''}>${sideTasks()}</section><section id="ec-side-panel-history" role="tabpanel" aria-labelledby="ec-side-tab-history" ${sidebarTab!=='history'?'hidden':''}>${historyView()}${record.active?`<form class="ec-form" id="ec-correction"><label class="ec-wide">Record to withdraw<select name="supersedes" required><option value="">Select record</option>${active().filter(e=>e.kind!=='correction').map(e=>`<option value="${esc(e._id)}">${esc(pretty(e.kind))} · ${esc(e.title)} · ${esc(date(e.occurredAt||e.createdAt))}</option>`).join('')}</select></label>${input('notes','Correction explanation','textarea')}<button>Withdraw record</button></form>`:''}</section></div>`;panel.querySelectorAll('[data-preview]').forEach(b=>b.onclick=()=>quickLook(b.dataset.preview));panel.querySelector('#ec-correction')?.addEventListener('submit',e=>saveForm(e,async data=>{await add({kind:'correction',title:'Record correction',...data});}));bindSideTasks(panel);panel.querySelectorAll('[data-side-tab]').forEach(button=>{const select=()=>{sidebarTab=button.dataset.sideTab;panel.querySelectorAll('[data-side-tab]').forEach(b=>{const selected=b.dataset.sideTab===sidebarTab;b.setAttribute('aria-selected',String(selected));b.tabIndex=selected?0:-1;panel.querySelector('#ec-side-panel-'+b.dataset.sideTab).hidden=!selected;});};button.onclick=select;button.onkeydown=event=>{if(!['ArrowLeft','ArrowRight','Home','End'].includes(event.key))return;event.preventDefault();const name=event.key==='Home'?'tasks':event.key==='End'?'history':sidebarTab==='tasks'?'history':'tasks';const next=panel.querySelector('[data-side-tab="'+name+'"]');next.click();next.focus();};});}
  function fieldSuggestions(key){const defaults={title:{notices:['Notice prepared','Notice delivered','Service attempt','Service evidence received'],communication:['Tenant phone call','Tenant email','Payment discussion','Follow-up requested'],'dates & tasks':['Review supporting documents','Contact tenant','Confirm hearing details'],court:['Hearing scheduled','Court filing recorded','Court order received'],closeout:['Keys returned','Move-out inspection','Final accounting'],expenses:['Court filing fee','Service fee','Attorney invoice']},method:['Personal delivery','Mail','Posting','Other'],owner:[record?.owner],recipient:[record?.snapshot?.tenantName],vendor:expenses.map(e=>e.vendor),court:['Justice of the Peace court'],nextAction:['Review supporting documents','Follow up with tenant','Confirm hearing details','Review final accounting']};let values=key==='title'?(defaults.title[tab]||[]):(defaults[key]||[]);const prior=(record?.entries||[]).map(e=>e[key]);return [...new Set([...values,...prior].filter(v=>typeof v==='string'&&v.trim()))].slice(0,25);}
  function setExpenseButtons(root,mode){root.querySelectorAll('[data-expense-mode]').forEach(b=>{const open=b.dataset.expenseMode===mode;b.textContent=open?'− Close form':b.dataset.expenseMode==='new'?'+ Add expense':'Link existing';b.setAttribute('aria-expanded',String(open));b.setAttribute('aria-controls','ec-expense-editor');});}
  function buildNote(data){const lines=[];if(data.title?.trim())lines.push(data.title.trim()+'.');const labels={noticeType:'Notice type',status:'Recorded status',occurredAt:'Date',dueAt:'Follow-up date',method:'Delivery method',recipient:'Recipient / participants',server:'Served by',owner:'Assigned to',channel:'Communication channel',eventType:'Event',court:'Court',caseNumber:'Court case number',location:'Location',attendees:'Attendees',outcome:'Recorded outcome',amount:'Amount',vendor:'Vendor / payee',category:'Category'};for(const [key,label] of Object.entries(labels)){const value=data[key];if(value==null||String(value).trim()==='')continue;lines.push(`${label}: ${['occurredAt','dueAt'].includes(key)?date(value):key==='amount'?money(value):['noticeType','status','channel','eventType','category'].includes(key)?String(value).replace(/-/g,' '):String(value)}.`);}if(data.documentId){const doc=documents.find(d=>String(d._id)===String(data.documentId));if(doc)lines.push('Supporting document: '+doc.name+'.');}return lines.join('\n');}
  function bindNoteDrafts(root){root.querySelectorAll('[data-draft-note]').forEach(button=>button.onclick=()=>{const form=button.closest('form'),notes=form?.elements.namedItem('notes');if(!notes)return;const draft=buildNote(Object.fromEntries(new FormData(form)));if(!draft)return;notes.value=notes.value.trim()?notes.value.trim()+'\n\n'+draft:draft;dirty=true;notes.focus();});}
  function sideTasks(){const tasks=active().filter(e=>e.kind==='task').sort((a,b)=>(a.status==='completed')-(b.status==='completed')||new Date(a.dueAt)-new Date(b.dueAt));return `<section class="ec-side-tasks"><div class="ec-side-task-head"><h3><i class="fas fa-list-check" aria-hidden="true"></i> Tasks <span class="ec-count">${tasks.filter(t=>t.status==='open').length}</span></h3>${record.active?'<button type="button" data-side-task-toggle aria-expanded="false" aria-controls="ec-side-task-form" title="Add task" aria-label="Add task"><i class="fas fa-plus" aria-hidden="true"></i></button>':''}</div>${record.active?`<form class="ec-form" id="ec-side-task-form" hidden>${input('title','Task title')}${input('owner','Assigned to','text',record.owner||'')}${input('dueAt','Due date','datetime-local')}${input('notes','Task notes','textarea')}<button type="submit">Save task</button><button type="button" data-side-task-cancel>Cancel</button></form>`:''}<div>${tasks.map(t=>`<article class="ec-side-task ${t.status==='completed'?'done':''}"><button type="button" data-side-task-complete="${esc(t._id)}" ${!record.active||t.status==='completed'?'disabled':''} aria-label="${esc(t.status==='completed'?'Completed: '+t.title:'Complete task: '+t.title)}"><i class="${t.status==='completed'?'fas fa-check-circle':'far fa-circle'}" aria-hidden="true"></i></button><div><strong>${esc(t.title)}</strong><small>${esc(t.owner||'Unassigned')}</small><small class="${t.status==='open'&&new Date(t.dueAt)<new Date()?'ec-overdue':''}">${esc(date(t.dueAt))}</small></div></article>`).join('')||'<p class="ec-muted">No tasks yet. Add the next follow-up.</p>'}</div></section>`;}
  function bindSideTasks(panel){const form=panel.querySelector('#ec-side-task-form');if(form){const toggle=panel.querySelector('[data-side-task-toggle]');const setOpen=open=>{form.hidden=!open;toggle.setAttribute('aria-expanded',String(open));toggle.setAttribute('aria-label',open?'Close task form':'Add task');if(open)form.querySelector('[name="title"]').focus();};panel.querySelectorAll('[data-side-task-toggle],[data-side-task-cancel]').forEach(b=>b.onclick=()=>{if(!canLeave())return;dirty=false;form.reset();setOpen(b.hasAttribute('data-side-task-cancel')?false:form.hidden);});form.querySelectorAll('[name="title"],[name="owner"],[name="dueAt"]').forEach(el=>el.required=true);form.addEventListener('submit',e=>saveForm(e,data=>add({kind:'task',status:'open',...data})));}panel.querySelectorAll('[data-side-task-complete]').forEach(b=>b.onclick=()=>{if(!canLeave())return;dirty=false;busy(panel,async()=>{record=await api('/'+record._id+'/tasks/'+b.dataset.sideTaskComplete+'/complete','POST',{revision:record.revision});flash('Task completed.');renderCase();});});}
  document.addEventListener('click',event=>{if(!view||view.hidden||!event.target.closest('.sidebar [data-sidebar-destination]'))return;if(!canLeave()){event.preventDefault();event.stopImmediatePropagation();return;}dirty=false;request++;view.hidden=true;record=null;document.querySelector('main.main-content')?.classList.remove('eviction-cases-open');},true);
})();
